#include <zephyr/kernel.h>
#include <zephyr/posix/time.h>
#include <zephyr/posix/signal.h>
#include <zephyr/posix/errno.h>
#include <zephyr/sys/util.h>
#include <zephyr/sys/slist.h>
#include <zephyr/init.h>

#define NSEC_PER_SEC 1000000000LL

#define TIMESPEC_VALID(ts) (((ts)->tv_nsec >= 0) && ((ts)->tv_nsec < NSEC_PER_SEC))

static inline uint64_t timespec_to_ns(const struct timespec *ts, enum k_clock_rounding_mode mode)
{
	uint64_t ns;

	if (unlikely(ts->tv_sec < 0 || !TIMESPEC_VALID(ts))) {
		return 0;
	}

	if (u64_mul_overflow(ts->tv_sec, NSEC_PER_SEC, &ns)) {
		return UINT64_MAX;
	}

	if (u64_add_overflow(ns, ts->tv_nsec, &ns)) {
		return UINT64_MAX;
	}

	return ns;
}

#ifdef CONFIG_POSIX_CLOCK
static void posix_timer_expiry_fn(struct k_timer *timer);

/*
 * We need to keep a list of timer objects created by the application.
 * This is required to map the timer object to the underlying kernel
 * timer object.
 */
static sys_slist_t posix_timer_list;

static struct k_spinlock lock;

struct posix_timer {
	sys_slist_node_t list_node;
	struct k_timer ktimer;
	timer_t timerid;
	struct sigevent sev;
	uint32_t reload_ticks;
	bool in_use;
};

/* FIXME: timerid should be unique system wide. */
static struct posix_timer timers[CONFIG_MAX_TIMER_COUNT];

static int posix_timer_init(void)
{
	sys_slist_init(&posix_timer_list);
	return 0;
}

SYS_INIT(posix_timer_init, APPLICATION, CONFIG_APPLICATION_INIT_PRIORITY);

static struct posix_timer *get_posix_timer(timer_t timerid)
{
	struct posix_timer *ptimer;

	SYS_SLIST_FOR_EACH_CONTAINER(&posix_timer_list, ptimer, list_node) {
		if (ptimer->timerid == timerid) {
			return ptimer;
		}
	}

	return NULL;
}

static void posix_timer_expiry_fn(struct k_timer *timer)
{
	struct posix_timer *ptimer;

	ptimer = CONTAINER_OF(timer, struct posix_timer, ktimer);

	if (ptimer->reload_ticks > 0) {
		k_timer_start(&ptimer->ktimer, K_TICKS(ptimer->reload_ticks),
			      K_TICKS(ptimer->reload_ticks));
	}

	if (ptimer->sev.sigev_notify == SIGEV_SIGNAL) {
		k_thread_kill((k_tid_t)ptimer->sev.sigev_notify_thread_id,
			      ptimer->sev.sigev_signo);
	} else if (ptimer->sev.sigev_notify == SIGEV_THREAD) {
		k_thread_create(ptimer->sev.sigev_notify_attributes,
				ptimer->sev.sigev_notify_stack,
				K_THREAD_STACK_SIZEOF(
					ptimer->sev.sigev_notify_stack),
				(k_thread_entry_t)ptimer->sev.sigev_notify_function,
				ptimer->sev.sigev_value.sival_ptr, NULL, NULL,
				K_PRIO_COOP(1), 0, K_NO_WAIT);
	}
}

int timer_create(clockid_t clockid, struct sigevent *sevp, timer_t *timerid)
{
	int i;
	k_spinlock_key_t key;
	struct posix_timer *ptimer = NULL;

	if (clockid != CLOCK_MONOTONIC) {
		errno = EINVAL;
		return -1;
	}

	if (sevp == NULL || timerid == NULL) {
		errno = EINVAL;
		return -1;
	}

	key = k_spin_lock(&lock);

	for (i = 0; i < CONFIG_MAX_TIMER_COUNT; i++) {
		if (timers[i].in_use == false) {
			ptimer = &timers[i];
			ptimer->in_use = true;
			break;
		}
	}

	k_spin_unlock(&lock, key);

	if (ptimer == NULL) {
		errno = EAGAIN;
		return -1;
	}

	ptimer->timerid = (timer_t)ptimer;
	*timerid = ptimer->timerid;
	ptimer->sev = *sevp;

	k_timer_init(&ptimer->ktimer, posix_timer_expiry_fn, NULL);
	sys_slist_append(&posix_timer_list, &ptimer->list_node);

	return 0;
}

int timer_delete(timer_t timerid)
{
	struct posix_timer *ptimer;

	ptimer = get_posix_timer(timerid);
	if (ptimer == NULL) {
		errno = EINVAL;
		return -1;
	}

	k_timer_stop(&ptimer->ktimer);
	sys_slist_find_and_remove(&posix_timer_list, &ptimer->list_node);
	ptimer->in_use = false;

	return 0;
}

int timer_gettime(timer_t timerid, struct itimerspec *its)
{
	uint64_t remaining_ns;
	uint64_t reload_ns;
	struct posix_timer *ptimer;

	ptimer = get_posix_timer(timerid);
	if (ptimer == NULL || its == NULL) {
		errno = EINVAL;
		return -1;
	}

	remaining_ns = k_timer_remaining_get(&ptimer->ktimer);
	if (remaining_ns == 0U) {
		/* Timer is not running */
		its->it_value.tv_sec = 0;
		its->it_value.tv_nsec = 0;
	} else {
		remaining_ns = k_ticks_to_ns_floor64(remaining_ns);
		its->it_value.tv_sec = remaining_ns / NSEC_PER_SEC;
		its->it_value.tv_nsec = remaining_ns % NSEC_PER_SEC;
	}

	reload_ns = k_ticks_to_ns_floor64(ptimer->reload_ticks);
	its->it_interval.tv_sec = reload_ns / NSEC_PER_SEC;
	its->it_interval.tv_nsec = reload_ns % NSEC_PER_SEC;

	return 0;
}

int timer_settime(timer_t timerid, int flags, const struct itimerspec *its,
		  struct itimerspec *oits)
{
	k_timeout_t duration, period;
	struct posix_timer *ptimer;

	ptimer = get_posix_timer(timerid);
	if (ptimer == NULL) {
		errno = EINVAL;
		return -1;
	}

	if (oits != NULL) {
		(void)timer_gettime(timerid, oits);
	}

	if (its == NULL || (its->it_value.tv_sec == 0 && its->it_value.tv_nsec == 0)) {
		k_timer_stop(&ptimer->ktimer);
		return 0;
	}

	if (!TIMESPEC_VALID(its->it_value) || !TIMESPEC_VALID(its->it_interval)) {
		errno = EINVAL;
		return -1;
	}

	duration = K_NSEC(timespec_to_ns(&its->it_value, K_CLOCK_ROUND_TO_NEAREST));
	period = K_NSEC(timespec_to_ns(&its->it_interval, K_CLOCK_ROUND_TO_NEAREST));

	ptimer->reload_ticks = period.ticks;

	if (flags & TIMER_ABSTIME) {
		struct timespec now;
		k_timeout_t remaining;
		uint64_t now_ns, its_ns;

		(void)clock_gettime(CLOCK_MONOTONIC, &now);
		now_ns = timespec_to_ns(&now, K_CLOCK_ROUND_DOWN);
		its_ns = timespec_to_ns(&its->it_value, K_CLOCK_ROUND_TO_NEAREST);

		if (its_ns > now_ns) {
			remaining = K_NSEC(its_ns - now_ns);
		} else {
			/* expire immediately */
			remaining = K_NO_WAIT;
		}
		duration = remaining;
	}

	k_timer_start(&ptimer->ktimer, duration, period);

	return 0;
}
#endif /* CONFIG_POSIX_CLOCK */

int clock_getres(clockid_t clock_id, struct timespec *res)
{
	uint64_t period_ns;

	if (res == NULL) {
		errno = EFAULT;
		return -1;
	}

	switch (clock_id) {
	case CLOCK_MONOTONIC:
		period_ns = k_ticks_to_ns_floor64(1);
		break;
#ifdef CONFIG_POSIX_CLOCK_REALTIME
	case CLOCK_REALTIME:
		period_ns = k_ticks_to_ns_floor64(1);
		break;
#endif
	default:
		errno = EINVAL;
		return -1;
	}

	res->tv_sec = period_ns / NSEC_PER_SEC;
	res->tv_nsec = period_ns % NSEC_PER_SEC;

	return 0;
}

int clock_gettime(clockid_t clock_id, struct timespec *ts)
{
	uint64_t ticks;
	uint64_t nsecs;

	if (ts == NULL) {
		errno = EFAULT;
		return -1;
	}

	switch (clock_id) {
	case CLOCK_MONOTONIC:
		ticks = k_uptime_ticks();
		nsecs = k_ticks_to_ns_floor64(ticks);
		ts->tv_sec = nsecs / NSEC_PER_SEC;
		ts->tv_nsec = nsecs % NSEC_PER_SEC;
		break;
#ifdef CONFIG_POSIX_CLOCK_REALTIME
	case CLOCK_REALTIME:
		(void)posix_clock_realtime_get(ts);
		break;
#endif
	default:
		errno = EINVAL;
		return -1;
	}

	return 0;
}

int clock_settime(clockid_t clock_id, const struct timespec *ts)
{
	if (ts == NULL) {
		errno = EFAULT;
		return -1;
	}

	if (!TIMESPEC_VALID(ts)) {
		errno = EINVAL;
		return -1;
	}

	switch (clock_id) {
#ifdef CONFIG_POSIX_CLOCK_REALTIME
	case CLOCK_REALTIME:
		return posix_clock_realtime_set(ts);
#endif
	case CLOCK_MONOTONIC:
	default:
		errno = EINVAL;
		return -1;
	}
}

int clock_nanosleep(clockid_t clock_id, int flags,
		    const struct timespec *rqtp, struct timespec *rmtp)
{
	uint64_t ns;
	k_timeout_t t;

	if (rqtp == NULL) {
		errno = EFAULT;
		return -1;
	}

	if (rqtp->tv_sec < 0 || !TIMESPEC_VALID(rqtp)) {
		errno = EINVAL;
		return -1;
	}

	if (clock_id != CLOCK_MONOTONIC) {
		errno = ENOTSUP;
		return -1;
	}

	ns = timespec_to_ns(rqtp, K_CLOCK_ROUND_TO_NEAREST);
	t = K_NSEC(ns);

	if (flags == 0) {
		k_sleep(t);
	} else if (flags == TIMER_ABSTIME) {
		uint64_t ticks = k_uptime_ticks();
		uint64_t current_ns = k_ticks_to_ns_floor64(ticks);

		if (ns > current_ns) {
			k_sleep(K_NSEC(ns - current_ns));
		}
	} else {
		errno = EINVAL;
		return -1;
	}

	if (rmtp != NULL) {
		rmtp->tv_sec = 0;
		rmtp->tv_nsec = 0;
	}

	return 0;
}
